import type { Lang } from './i18n'

// The dictionary for the personalisation, investigation, scan-visibility, risk,
// export and onboarding features. It is a separate file only because i18n.tsx
// was already long; `t()` merges the two and cannot tell them apart.
//
// Each entry is written positionally — e(en, vi, it, zh, es, de, fr) — so one
// key is one line and a missing language is a type error rather than a silent
// fall back to English three releases later.

type Entry = Record<Lang, string>

const e = (en: string, vi: string, it: string, zh: string, es: string, de: string, fr: string): Entry =>
  ({ en, vi, it, zh, es, de, fr })

